/**
 * Debounces a function call.
 * 
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to wait before executing the function again.
 * @returns {Function} A new function that performs the debouncing logic.
 */
function debounce(func, wait) {
  let timeout;

  return function (...args) {
    // Clear any existing timeout
    clearTimeout(timeout);

    // Set a new timeout
    timeout = setTimeout(() => {
      func.apply(this, args);
    }, wait);
  };
}
